import React, { useState } from "react";
import { motion } from "framer-motion";

export default function NewEntry() {
  const [form, setForm] = useState({
    title: "",
    category: "",
    date: "",
    mood: "",
    tags: "",
    security: "Private",
    notes: "",
    attachment: null,
  });

  const handleChange = (e) => {
    const { name, value, files } = e.target;
    setForm({ ...form, [name]: files ? files[0] : value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    alert("Entry Saved ✅\n" + JSON.stringify(form, null, 2));
  };

  return (
    <motion.div
      className="max-w-3xl mx-auto bg-white shadow-xl rounded-2xl p-8"
      initial={{ opacity: 0, y: 30 }}
      animate={{ opacity: 1, y: 0 }}
    >
      <h2 className="text-2xl font-bold text-indigo-600 mb-6">📝 New Entry</h2>
      <form onSubmit={handleSubmit} className="space-y-6">
        {/* Title */}
        <div>
          <label className="block text-gray-600 font-medium">Title</label>
          <input
            type="text"
            name="title"
            value={form.title}
            onChange={handleChange}
            className="w-full mt-2 p-3 border rounded-xl"
            required
          />
        </div>

        {/* Category */}
        <div>
          <label className="block text-gray-600 font-medium">Category</label>
          <select
            name="category"
            value={form.category}
            onChange={handleChange}
            className="w-full mt-2 p-3 border rounded-xl"
          >
            <option>Study</option>
            <option>Personal</option>
            <option>Work</option>
            <option>Other</option>
          </select>
        </div>

        {/* Date */}
        <div>
          <label className="block text-gray-600 font-medium">Date</label>
          <input
            type="date"
            name="date"
            value={form.date}
            onChange={handleChange}
            className="w-full mt-2 p-3 border rounded-xl"
          />
        </div>

        {/* Mood */}
        <div>
          <label className="block text-gray-600 font-medium">Mood</label>
          <select
            name="mood"
            value={form.mood}
            onChange={handleChange}
            className="w-full mt-2 p-3 border rounded-xl"
          >
            <option>😊 Happy</option>
            <option>😐 Neutral</option>
            <option>😔 Sad</option>
            <option>😡 Angry</option>
          </select>
        </div>

        {/* Tags */}
        <div>
          <label className="block text-gray-600 font-medium">Tags</label>
          <input
            type="text"
            name="tags"
            value={form.tags}
            onChange={handleChange}
            placeholder="Comma separated (e.g. Study, Motivation)"
            className="w-full mt-2 p-3 border rounded-xl"
          />
        </div>

        {/* Security */}
        <div>
          <label className="block text-gray-600 font-medium">Security Level</label>
          <select
            name="security"
            value={form.security}
            onChange={handleChange}
            className="w-full mt-2 p-3 border rounded-xl"
          >
            <option>Private</option>
            <option>Shared</option>
            <option>Public</option>
          </select>
        </div>

        {/* Notes */}
        <div>
          <label className="block text-gray-600 font-medium">Notes</label>
          <textarea
            name="notes"
            value={form.notes}
            onChange={handleChange}
            rows="5"
            className="w-full mt-2 p-3 border rounded-xl"
          ></textarea>
        </div>

        {/* Attachment */}
        <div>
          <label className="block text-gray-600 font-medium">Attachment</label>
          <input
            type="file"
            name="attachment"
            onChange={handleChange}
            className="mt-2"
          />
        </div>

        {/* Submit */}
        <motion.button
          whileHover={{ scale: 1.05 }}
          type="submit"
          className="w-full bg-indigo-600 text-white py-3 rounded-xl font-semibold"
        >
          Save Entry
        </motion.button>
      </form>
    </motion.div>
  );
}
